const available_components = $('create a structed knowledge pack').first().json.available_components;

const related_systems =$('create a structed knowledge pack').first().json.related_systems;

const components = [
  ...new Set(
    (available_components || [])
      .map(c => c.component_name)
      .filter(Boolean)
  )
];

const assemblies = [
  ...new Set(
    (related_systems || [])
      .map(s => s.system_name)
      .filter(Boolean)
  )
];

return [{
  json: {
    components,
    assemblies
  }
}];

// Get raw AI output
let response = $input.first().json.output[0].content[0].text;

// Remove markdown wrappers if AI returns ```json
response = response
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const pack = JSON.parse(response);

// Get mission_id from Create Mission node
const missionId = $('library creator').first().json.body["id"];

// Structure everything for DB insertion
const structured = {

  related_systems: (pack.related_systems || []).map(item => ({
    mission_id: missionId,
    ...item
  })),

  available_components: (pack.available_components || []).map(item => ({
    mission_id: missionId,
    ...item
  })),

  available_materials: (pack.available_materials || []).map(item => ({
    mission_id: missionId,
    ...item
  })),

  manufacturing_methods: (pack.manufacturing_methods || []).map(item => ({
    mission_id: missionId,
    ...item
  })),

  scientific_knowledge: (pack.scientific_knowledge || []).map(item => ({
    mission_id: missionId,
    ...item
  })),

  design_bottlenecks: (pack.design_bottlenecks || []).map(item => ({
    mission_id: missionId,
    ...item
  })),

  micro_component_opportunities:
    (pack.micro_component_opportunities || []).map(item => ({
      mission_id: missionId,
      ...item
    })),

  engineering_inventory:
    (pack.engineering_inventory || []).map(item => ({
      mission_id: missionId,
      ...(typeof item === 'string'
        ? { asset_name: item }
        : item)
    }))
};

return [{ json: structured }];

const present_components = [];
const missing_components = [];

const present_assemblies = [];
const missing_assemblies = [];

for (const item of $input.all()) {
  const row = item.json;

    // Assemblies
  if (row.assembly_name) {
    if (row.status === "present") {
      present_assemblies.push({
        assembly_id: row.assembly_id,
        assembly_name: row.assembly_name
      });
    } else {
      missing_assemblies.push(row.assembly_name);
    }
  }

  // Components
  if (row.component_name) {
    if (row.status === "present") {
      present_components.push({
        component_id: row.component_id,
        component_name: row.component_name
      });
    } else {
      missing_components.push(row.component_name);
    }
  }
}

return [{
  json: {
    present_assemblies,
    missing_assemblies,
    present_components,
    missing_components
  }
}];

const items = $input;
return items.map(item => {
  return {
    json: {
      asset: item.json.asset_name,
      length: item.json.body.length,
      first500: item.json.body.substring(0, 500)
    }
  };
});

const missing_assemblies = $('If').first().json.missing_assemblies;
const missing_components = $('If').first().json.missing_components;

const assets = [
  ...missing_assemblies.map(name => ({
    asset_type: "assembly",
    asset_name: name
  })),
  ...missing_components.map(name => ({
    asset_type: "component",
    asset_name: name
  }))
];

return assets;

const assetName = $('Loop Over Items').first().json.asset_name;

const normalize = (str) => {
  return str.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
};

const assetTokens = [...new Set(normalize(assetName).split(' '))];

const scoredModels = $input.first().json.body.models

  // Remove invalid entries first
  .filter(m => m.title && m.url && m.url !== "#")

  // Then score the remaining models
  .map(model => {
    const titleTokens = [...new Set(normalize(model.title).split(' '))];

    const matches = assetTokens.filter(token =>
      titleTokens.includes(token)
    ).length;

    const score = matches / assetTokens.length;

    return {
      ...model,
      score
    };
  });

scoredModels.sort((a, b) => b.score - a.score);

return scoredModels.map(model => ({ json: model }));

