// AI models array
const aiModels = $('Code in JavaScript6').first().json.ai_models;

// Database models (can be null)
const dbModels = null;

// Create a Set of existing model names
const existing = new Set(
  (dbModels ?? [])
    .map(item => item.model_name.toLowerCase())
);

// Arrays to hold results
const found = [];
const missing = [];

// Compare
for (const model of aiModels) {

  if (existing.has(model.model_name.toLowerCase())) {
    found.push(model);
  } else {
    missing.push(model);
  }

}

// Return as ONE n8n item
return [
  {
    json: {
      found_models: found,
      missing_models: missing
    }
  }
];

const models = $input.first().json.missing_models ;

// Convert each model into an individual n8n item
